content.query:
let r = requests | where timestamp {TimeRange} | where url !endswith '/robots933456.txt';
let total = toscalar(r | count);
let serverPct = toscalar(r | summarize iff(count() == 0, 0.0, round(100.0 * countif(toint(resultCode) between (500 .. 599)) / count(), 2)));
let clientPct = toscalar(r | summarize iff(count() == 0, 0.0, round(100.0 * countif(toint(resultCode) between (400 .. 499)) / count(), 2)));
let p95 = toscalar(r | summarize round(percentile(duration, 95), 0));
let ex = exceptions | where timestamp {TimeRange} | extend Source = iff(cloud_RoleName == "CheckMate.Web", "Browser", "API") | join kind=leftouter (dependencies | where timestamp {TimeRange} | where cloud_RoleName == "CheckMate.Web" and success == true and isnotempty(session_Id) | summarize LastApiSuccess = max(timestamp) by session_Id) on session_Id | extend Handled = Source == "API" and severityLevel < 3, Synthetic = client_Browser startswith "HeadlessChrome", NetworkError = Source == "Browser" and outerMessage has_any ("Failed to fetch", "Load failed", "NetworkError") | extend Recovered = NetworkError and LastApiSuccess > timestamp | extend Status = iff(Handled or Synthetic or Recovered, "Expected", "Needs attention"), Reason = case(Handled, "Logged below Error, such as a retried SQL connection", Source == "API", "Logged as an error", Synthetic, "Automated test traffic (CI smoke tests or Generate Load)", Recovered, "Network error; a later API call in the same session succeeded", NetworkError, "Network error with no later successful API call: the API was unreachable (cold start, outage or CORS) or the user gave up", "Frontend error");
let apiErrors = toscalar(ex | where Source == "API" and Status == "Needs attention" | count);
let webErrors = toscalar(ex | where Source == "Browser" and Status == "Needs attention" | count);
let expected = toscalar(ex | where Status == "Expected" | count);
let uptime = toscalar(availabilityResults | where timestamp {TimeRange} | summarize iff(count() == 0, real(null), round(100.0 * countif(success == 1) / count(), 1)));
let pv = pageViews | where timestamp {TimeRange};
let viewCount = toscalar(pv | count);
let users = toscalar(pv | summarize dcount(user_Id));
let sessions = toscalar(pv | summarize dcount(session_Id));
let rows = union
    (print Order = 0, Metric = "Health check uptime", Value = iff(isnull(uptime), "No data", strcat(uptime, "%")),
        Health = case(isnull(uptime), "Warning", uptime < 95, "Critical", uptime < 100, "Warning", "Healthy")),
    (print Order = 1, Metric = "API requests", Value = tostring(total), Health = "Info"),
    (print Order = 2, Metric = "Server errors (5xx)", Value = strcat(serverPct, "%"),
        Health = case(serverPct >= 5, "Critical", serverPct >= 1, "Warning", "Healthy")),
    (print Order = 3, Metric = "Client errors (4xx)", Value = strcat(clientPct, "%"), Health = "Info"),
    (print Order = 4, Metric = "P95 response time", Value = strcat(coalesce(p95, 0.0), " ms"),
        Health = case(isnull(p95), "Info", p95 >= 3000, "Critical", p95 >= 1000, "Warning", "Healthy")),
    (print Order = 5, Metric = "API errors", Value = tostring(apiErrors),
        Health = case(apiErrors >= 10, "Critical", apiErrors > 0, "Warning", "Healthy")),
    (print Order = 6, Metric = "Browser errors", Value = tostring(webErrors),
        Health = case(webErrors >= 10, "Critical", webErrors > 0, "Warning", "Healthy")),
    (print Order = 7, Metric = "Expected exceptions", Value = tostring(expected), Health = "Info"),
    (print Order = 8, Metric = "Page views", Value = tostring(viewCount), Health = "Info"),
    (print Order = 9, Metric = "Users", Value = tostring(users), Health = "Info"),
    (print Order = 10, Metric = "Sessions", Value = tostring(sessions), Health = "Info");
let worst = toscalar(rows | summarize max(case(Health == "Critical", 2, Health == "Warning", 1, 0)));
union rows,
    (print Order = -1, Metric = "Overall", Value = case(worst == 2, "Unhealthy", worst == 1, "Needs a look", "Healthy"),
        Health = case(worst == 2, "Critical", worst == 1, "Warning", "Healthy"))
| order by Order asc
| project Metric, Value, Health

availabilityResults
| where timestamp {TimeRange}
| summarize ["Availability %"] = round(100.0 * countif(success == 1) / count(), 1) by bin(timestamp, {TimeRange:grain})

pageViews
| where timestamp {TimeRange}
| summarize Views = count(), Users = dcount(user_Id) by bin(timestamp, {TimeRange:grain})

pageViews
| where timestamp {TimeRange}
| summarize Views = count(), Users = dcount(user_Id), Sessions = dcount(session_Id) by bin(timestamp, {TimeRange:grain})
